#!/bin/bash

# ============================================================================
# Run only the tests related to files changed vs HEAD (staged, unstaged and
# untracked). Quiet: failures plus a one-line summary. Falls back to the full
# suite when a change cannot be mapped to tests. Generated by repo_contract.
# ============================================================================

set -euo pipefail

cd "$(git rev-parse --show-toplevel)"
# mcp-server/ is its own subproject: its tests need the `mcp` package, which
# only its venv has (mcp-server/scripts/setup_mcp.sh), never system python.
MCP_PYTHON="${MCP_PYTHON:-${HOME}/.venvs/control-panel-mcp/bin/python}"
CHANGED=()
MCP_CHANGED=0
while IFS= read -r f; do
    [[ -z "$f" || ! -e "$f" ]] && continue
    if [[ "$f" == mcp-server/* ]]; then MCP_CHANGED=1; else CHANGED+=("$f"); fi
done < <({ git diff --name-only HEAD 2>/dev/null || true; git ls-files --others --exclude-standard; } | sort -u)

mcp_run() {
    if [[ ! -x "$MCP_PYTHON" ]]; then
        echo "mcp-server changed but $MCP_PYTHON is missing: run mcp-server/scripts/setup_mcp.sh" >&2
        return 1
    fi
    (cd mcp-server && "$MCP_PYTHON" -m pytest -q --tb=short)
}

if [[ $MCP_CHANGED -eq 1 ]]; then
    mcp_run || exit $?
    [[ ${#CHANGED[@]} -eq 0 ]] && exit 0
fi

pytest_run() {
    if [[ -f uv.lock ]]; then uv run pytest "$@"
    elif [[ -f poetry.lock ]]; then poetry run pytest "$@"
    else python3 -m pytest "$@"; fi
}

if grep -qs testmon pyproject.toml requirements*.txt; then
    pytest_run --testmon -q --tb=short; exit $?
fi

full=0
tests=()
for f in "${CHANGED[@]}"; do
    case "$f" in
        */conftest.py | conftest.py | pyproject.toml | requirements*.txt | pytest.ini | setup.cfg) full=1 ;;
        *.py)
            base="$(basename "$f" .py)"
            if [[ "$base" == test_* || "$base" == *_test ]]; then
                tests+=("$f")
            else
                while IFS= read -r t; do tests+=("$t"); done \
                    < <(git ls-files "*test_${base}.py" "*${base}_test.py")
            fi
            ;;
    esac
done

if [[ $full -eq 0 && ${#CHANGED[@]} -eq 0 ]]; then echo "no changes vs HEAD: nothing to test"; exit 0; fi
if [[ $full -eq 0 && ${#tests[@]} -gt 0 ]]; then pytest_run -q --tb=short --no-cov "${tests[@]}"; exit $?; fi
if [[ $full -eq 0 ]] && ! printf '%s\n' "${CHANGED[@]}" | grep -q '\.py$'; then
    echo "no python changes: nothing to test"; exit 0
fi
echo "no mapped tests: running full suite"
pytest_run -q --tb=short
